  "description": "N-Tier PHP movie watchlist application",
  "type": "project",
  "require": {
    "php": ">=8.2"
  },
  "require-dev": {
    "phpunit/phpunit": "^11.0"
  },
  "autoload": {
    "psr-4": {
      "App\\": "src/"
    }
  },
  "autoload-dev": {
    "psr-4": {
      "Tests\\": "tests/"
    }
  },
  "scripts": {
    "serve": "php -S localhost:8000 -t public",
    "test": "phpunit"
  }
}

@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Fraunces:opsz,wght@9..144,500;9..144,650&display=swap');

:root {
    --ink: #202322;
    --muted: #68716c;
    --paper: #f5f3ed;
    --warm: #e7dfd0;
    --accent: #cf5b3e;
    --line: #d7d4ca;
    --white: #fffdf8;
}

* { box-sizing: border-box; }
body { margin: 0; color: var(--ink); background: var(--paper); font-family: 'DM Mono', monospace; line-height: 1.6; }
a { color: inherit; text-decoration-thickness: 1px; text-underline-offset: 4px; }
.site-header { display: flex; align-items: center; justify-content: space-between; max-width: 1180px; margin: 0 auto; padding: 28px 32px; }
.brand { font-family: Fraunces, Georgia, serif; font-size: 1.35rem; font-weight: 650; text-decoration: none; letter-spacing: -.02em; }
.brand span { color: var(--accent); }
nav { display: flex; align-items: center; gap: 24px; font-size: .78rem; }
.inline-form { display: inline; }
.page-shell { max-width: 1180px; min-height: calc(100vh - 100px); margin: 0 auto; padding: 40px 32px 80px; }
.hero { max-width: 850px; padding: 8vh 0 10vh; }
.eyebrow { color: var(--accent); font-size: .72rem; letter-spacing: .08em; text-transform: uppercase; }
h1, h2 { font-family: Fraunces, Georgia, serif; font-weight: 500; line-height: 1.05; letter-spacing: -.03em; }
h1 { max-width: 780px; margin: 18px 0; font-size: clamp(3.5rem, 8vw, 7rem); }
h1 em { color: var(--accent); font-style: normal; }
h2 { font-size: 2rem; margin: 10px 0; }
.hero-copy { max-width: 570px; color: var(--muted); font-size: 1rem; }
.hero-actions { display: flex; align-items: center; gap: 24px; margin-top: 38px; }
.button { display: inline-block; border: 1px solid var(--accent); padding: 14px 20px; color: var(--white); background: var(--accent); cursor: pointer; font: inherit; font-size: .76rem; text-decoration: none; }
.button:hover { background: var(--ink); border-color: var(--ink); }
.button-small { padding: 9px 14px; }
.button-quiet { border: 0; padding: 0; color: var(--ink); background: transparent; text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 4px; }
.text-link { font-size: .76rem; }
.feature-strip { display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid var(--line); }
.feature-strip article { min-height: 180px; padding: 25px 28px 20px 0; border-right: 1px solid var(--line); }
.feature-strip article:not(:first-child) { padding-left: 28px; }
.feature-strip article:last-child { border-right: 0; }
.feature-strip span { color: var(--accent); font-size: .72rem; }
.feature-strip p, .page-heading p, .empty-state p { color: var(--muted); font-size: .82rem; max-width: 520px; }
.auth-panel { width: min(100%, 490px); margin: 7vh auto; padding: 48px; background: var(--white); border: 1px solid var(--line); }
.auth-panel h1 { font-size: 4rem; }
.form-stack { display: grid; gap: 20px; margin-top: 32px; }
label { display: grid; gap: 7px; font-size: .74rem; }
input { width: 100%; border: 1px solid var(--line); padding: 14px; color: var(--ink); background: var(--paper); font: inherit; font-size: .85rem; }
input:focus { outline: 2px solid var(--accent); outline-offset: 2px; }
small, .form-note { color: var(--muted); font-size: .7rem; }
.form-note { margin-top: 24px; }
.alert { margin: 0 auto 24px; max-width: 490px; padding: 13px 16px; border-left: 3px solid var(--accent); color: var(--accent); background: #f5e3dc; font-size: .75rem; }
.page-heading { padding: 7vh 0 5vh; border-bottom: 1px solid var(--line); }
.page-heading h1 { font-size: clamp(3rem, 7vw, 6rem); }
.empty-state { padding: 70px 0; }
.empty-mark { color: var(--accent); font-family: Fraunces, Georgia, serif; font-size: 5rem; line-height: 1; }
@media (max-width: 640px) {
    .site-header { padding: 22px 20px; }
    nav { gap: 12px; }
    .page-shell { padding: 20px 20px 60px; }
    h1 { font-size: 3.5rem; }
    .hero { padding-top: 8vh; }
    .hero-actions { align-items: flex-start; flex-direction: column; gap: 18px; }
    .feature-strip { grid-template-columns: 1fr; }
    .feature-strip article, .feature-strip article:not(:first-child) { min-height: auto; padding: 22px 0; border-right: 0; border-bottom: 1px solid var(--line); }
    .auth-panel { margin: 5vh 0; padding: 30px 24px; }
    .auth-panel h1 { font-size: 3.2rem; }
}

